with flattened as (select id, customer_id, created_at, coupon_codes, item.product_id, item.qty, item.price, item.promo from carts lateral view outer explode(items) x as item) select promo, case when product_id >= 8 then 'PREMIUM' else 'STANDARD' end as product_id_tier, case when qty >= 4 then 'HIGH' else 'LOW' end as qty_tier, percentile_approx(product_id, 0.95) as product_id_p95, approx_percentile(qty, array(0.25, 0.5, 0.75)) as qty_quartiles, sum(case when promo = 'VIP' then price else 0 end) as vip_price from flattened group by promo, case when product_id >= 8 then 'PREMIUM' else 'STANDARD' end, case when qty >= 4 then 'HIGH' else 'LOW' end order by product_id_tier;
